The old .eslintrc.json had custom rules for 'semi', 'quotes', 'curly', and 'prefer-const' that enforced specific code style preferences (e.g., always use semicolons, double quotes). The new eslint.config.js uses 'noStyle: true' which disables all style rules, delegating formatting entirely to Prettier. Verify that Prettier is configured to match these style preferences (e.g., semicolons, double quotes) to maintain consistency with the previous linting behavior.
```suggestion
const neostandard = require('neostandard')
const prettierPlugin = require('eslint-plugin-prettier')

module.exports = [
    ...neostandard({
        env: ['browser'],
        ignores: neostandard.resolveIgnoresFromGitignore(),
        noStyle: true,
    }),
    {
        plugins: {
            prettier: prettierPlugin,
        },
        rules: {
            // Match previous style preferences: semicolons and double quotes
            'prettier/prettier': [
                'error',
                {
                    semi: true,
                    singleQuote: false,
                },
            ],
            // Preserve previous lint behavior for curly braces and prefer-const
            curly: 'error',
            'prefer-const': 'error',
        },
    },
```

